def f(I):
    h,w=len(I),len(I[0]); O=[r[:] for r in I]
    seen=set()
    def comp(start):
        st=[start]; seen.add(start); cc=[]
        while st:
            a,b=st.pop(); cc.append((a,b))
            for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                ny,nx=a+dy,b+dx
                if 0<=ny<h and 0<=nx<w and I[ny][nx]==5 and (ny,nx) not in seen:
                    seen.add((ny,nx)); st.append((ny,nx))
        return cc
    for i in range(h):
        for j in range(w):
            if I[i][j]==5 and (i,j) not in seen:
                cc=comp((i,j))
                ys=[y for y,_ in cc]; xs=[x for _,x in cc]
                r0,r1,c0,c1=min(ys),max(ys),min(xs),max(xs)
                gaps=[]
                for x in range(c0,c1+1):
                    if I[r0][x]==0: gaps.append(('top',x))
                    if I[r1][x]==0: gaps.append(('bottom',x))
                for y in range(r0,r1+1):
                    if I[y][c0]==0: gaps.append(('left',y))
                    if I[y][c1]==0: gaps.append(('right',y))
                assert len(gaps)==1,(gaps,I)
                side,pos=gaps[0]
                # fill interior with 2
                for y in range(r0,r1+1):
                    for x in range(c0,c1+1):
                        if I[y][x]!=5: O[y][x]=2
                # ray away from nearer wall, to grid edge
                if side=='top':
                    step = -1 if pos > (c0+c1)/2 else 1
                    rr=r0-1
                    rng = list(range(pos, -1, -1)) if step<0 else list(range(pos, w))
                elif side=='bottom':
                    step = 1 if pos < (c0+c1)/2 else -1
                    rr=r1+1
                    rng = list(range(pos, w)) if step>0 else list(range(pos, -1, -1))
                elif side=='left':
                    step = -1 if pos > (r0+r1)/2 else 1
                    cc_=c0-1
                    rng = list(range(pos, -1, -1)) if step<0 else list(range(pos, h))
                else:  # right
                    step = 1 if pos < (r0+r1)/2 else -1
                    cc_=c1+1
                    rng = list(range(pos, h)) if step>0 else list(range(pos, -1, -1))
                cells = [(rr,x) for x in rng] if side in('top','bottom') else [(y,cc_) for y in rng]
                for cy,cx in cells:
                    if 0<=cy<h and 0<=cx<w and O[cy][cx]==0: O[cy][cx]=2
    return O
